let adminSection='shops',adminSub='list',adminQuery='';const adminPage=document.createElement('section');adminPage.id='adminPage';adminPage.hidden=true;document.body.append(adminPage);
function openAdmin(section='shops',sub='list'){adminSection=section;adminSub=sub;if($('dialog').open)$('dialog').close();applicationPage.hidden=true;sellerReviewPage.hidden=true;document.querySelector('.app').hidden=true;adminPage.hidden=false;window.history.replaceState(null,'',location.pathname+location.search+'#admin-'+section);drawAdmin();}
function leaveAdmin(){adminPage.hidden=true;document.querySelector('.app').hidden=false;window.history.replaceState(null,'',location.pathname+location.search);render();}
function adminTable(head,rows){return `<div class="adminTableScroll"><table class="adminTable"><thead><tr>${head.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.length?rows.join(''):`<tr><td colspan="${head.length}" class="empty">暂无记录</td></tr>`}</tbody></table></div>`;}
function adminBtn(text,kind,id){return `<button data-admin-kind="${kind}" data-admin-id="${id}">${text}</button>`;}
function drawAdmin(){refreshAdminCatalog();const subs=adminSection==='shops'?[['list','店铺列表'],['applications','开店审核'],['qualifications','资质审核'],['requests','恢复营业申请'],['reports','举报'],['history','处理记录']]:[['list','商品列表'],['requests','商品复核申请'],['reports','举报'],['history','处理记录']];adminPage.innerHTML=`<header class="adminHeader"><strong>商城管理</strong><span>管理员预览 · 模拟审核</span><button id="adminLeave">返回买家</button></header><div class="adminShell"><aside class="adminSide"><button data-admin-main="shops" class="${adminSection==='shops'?'active':''}">店铺管理</button><button data-admin-main="products" class="${adminSection==='products'?'active':''}">商品管理</button></aside><main class="adminMain"><h1>${adminSection==='shops'?'店铺管理':'商品管理'}</h1><nav class="adminTabs">${subs.map(([id,label])=>`<button data-admin-sub="${id}" class="${adminSub===id?'active':''}">${label}</button>`).join('')}</nav><div class="adminToolbar"><input id="adminSearch" aria-label="搜索列表" placeholder="按名称或编号搜索" value="${escapeHTML(adminQuery)}"><button id="adminSearchGo">搜索</button><button id="adminSeed">载入审核演示资料</button></div>${adminRows()}</main></div>`;$('adminLeave').onclick=leaveAdmin;adminPage.querySelectorAll('[data-admin-main]').forEach(b=>b.onclick=()=>{adminQuery='';openAdmin(b.dataset.adminMain);});adminPage.querySelectorAll('[data-admin-sub]').forEach(b=>b.onclick=()=>{adminQuery='';adminSub=b.dataset.adminSub;drawAdmin();});$('adminSearchGo').onclick=()=>{adminQuery=$('adminSearch').value.trim();drawAdmin();};$('adminSeed').onclick=()=>{try{seedAdmin();}catch(e){toast(e.message);}};adminPage.querySelectorAll('[data-admin-kind]').forEach(b=>b.onclick=()=>{const k=b.dataset.adminKind,id=b.dataset.adminId;if(k==='shop'||k==='product')adminEntity(k,+id);else if(k==='report')adminReportReview(id);else if(k==='application')reviewApplication();else if(k==='qualification')reviewQualification();else adminRequestReview(k==='shopRequest'?'shop':'product',+id);});}
function adminRows(){const match=t=>String(t).includes(adminQuery);if(adminSub==='list'&&adminSection==='shops')return adminTable(['编号','店铺名称','营业状态','待处理举报','操作'],shops.map((name,id)=>({name,id})).filter(x=>match(x.name+' '+x.id)).map(({name,id})=>`<tr><td>${id}</td><td>${escapeHTML(name)}</td><td>${shopSupervision[id].stopped?'暂停营业':'正常营业'}</td><td>${demoReports.filter(r=>r.target.shop===id&&r.status==='待处理').length}</td><td>${adminBtn('查看 / 处理','shop',id)}</td></tr>`));if(adminSub==='list')return adminTable(['商品编号','商品名称','所属店铺','状态','举报数','操作'],[...adminCatalog.values()].filter(p=>!createdProducts.find(x=>x.productId===p.id)?.deleted&&match(p.name+' '+p.id)).map(p=>`<tr><td>${p.id}</td><td>${escapeHTML(p.name)}</td><td>${escapeHTML(shops[p.shop])}</td><td>${productControl(p.id).blocked?'紧急下架':shopSupervision[p.shop].stopped?'店铺停业':products.some(x=>x.id===p.id)?'在售':'已下架'}</td><td>${demoReports.filter(r=>r.target.kind==='product'&&r.target.id===p.id).length}</td><td>${adminBtn('核查 / 处理','product',p.id)}</td></tr>`));if(adminSub==='reports')return adminTable(['举报编号','对象','原因','状态','操作'],demoReports.filter(r=>(adminSection==='products'?r.target.kind==='product':r.target.kind==='shop')&&match(r.target.name+' '+r.id)).map(r=>`<tr><td>${r.id}</td><td>${escapeHTML(r.target.name)}</td><td>${escapeHTML(r.reason)}</td><td>${r.status}</td><td>${adminBtn('查看举报','report',r.id)}</td></tr>`));if(adminSub==='applications')return adminTable(['店名','主体','执照编号','状态','操作'],shopApplication?[`<tr><td>${escapeHTML(shopApplication.name)}</td><td>${escapeHTML(shopApplication.subject||'示例主体')}</td><td>${escapeHTML(shopApplication.license)}</td><td>${{PENDING:'待审核',APPROVED:'已通过',REJECTED:'已驳回'}[shopApplication.status]}</td><td>${adminBtn('查看申请','application','0')}</td></tr>`]:[]);if(adminSub==='qualifications')return adminTable(['店铺','资质类型','证件编号','有效期','状态','操作'],qualificationRecord?[`<tr><td>${escapeHTML(shops[0])}</td><td>${escapeHTML(qualificationRecord.type)}</td><td>${escapeHTML(qualificationRecord.number)}</td><td>${qualificationRecord.expiry}</td><td>${qualificationRecord.status}</td><td>${adminBtn('查看申请','qualification','0')}</td></tr>`]:[]);if(adminSub==='requests'){const pairs=adminSection==='shops'?shopSupervision.map((s,id)=>[id,s]):Object.entries(productSupervision);return adminTable(['对象','整改说明','状态','操作'],pairs.filter(([id,s])=>s.request).map(([id,s])=>`<tr><td>${escapeHTML(adminSection==='shops'?shops[id]:adminCatalog.get(+id)?.name||id)}</td><td>${escapeHTML(s.request.reason)}</td><td>${s.request.status}</td><td>${adminBtn('审核申请',adminSection==='shops'?'shopRequest':'productRequest',id)}</td></tr>`));}return adminTable(['时间','对象','操作','说明'],adminRecords.filter(r=>(adminSection==='shops'?r.scope==='shop':r.scope==='product')&&match(r.reason+' '+r.id)).map(r=>`<tr><td>${r.time}</td><td>${escapeHTML(r.scope==='shop'?shops[r.id]:adminCatalog.get(+r.id)?.name||r.id)}</td><td>${r.action}</td><td>${escapeHTML(r.reason)}</td></tr>`));}
function adminEntity(scope,id){const p=scope==='product'?adminCatalog.get(id):null,shop=p?p.shop:id;const s=scope==='shop'?shopSupervision[id]:productControl(id);modal(scope==='shop'?'店铺监督':'商品核查',`<h2>${escapeHTML(p?.name||shops[id])}</h2><p>所属店铺：${escapeHTML(shops[shop])}</p><p>状态：${s.stopped?'暂停营业':s.blocked?'紧急下架':scope==='shop'?'正常营业':s.listed?'在售':'已下架'}</p>${p?`<p>${escapeHTML(p.description||'商品资料')}</p>${adminTable(['规格','价格','可售库存'],p.variants.map(v=>`<tr><td>${escapeHTML(v.name)}</td><td>${money(v.price)}</td><td>${v.stock}</td></tr>`))}`:''}<div class="adminControls"><button id="entityWarn">警告商家</button><button id="entityRestrict" ${s.stopped||s.blocked?'disabled':''}>${scope==='shop'?'暂停营业':'紧急下架'}</button><button id="entitySeller">店主整改预览</button></div><h3>处理记录</h3>${s.records.map(r=>`<p>${r.time} · ${adminActionLabel(r.action)}：${escapeHTML(r.reason)}</p>`).join('')||'<p>暂无记录</p>'}`);$('entityWarn').onclick=()=>adminActionForm(scope,id,'warn');$('entityRestrict').onclick=()=>adminActionForm(scope,id,scope==='shop'?'stop':'emergency');$('entitySeller').onclick=()=>sellerRemediation(shop);}
function adminActionForm(scope,id,action,reportId){modal(adminActionLabel(action),`<p>处理对象：${escapeHTML(scope==='shop'?shops[id]:adminCatalog.get(id)?.name)}</p><label class="reportField">处理说明<textarea id="adminReason" required></textarea></label><p id="adminError" role="alert"></p><div class="orderActions"><button id="adminAbort">返回</button><button id="adminConfirm" class="primary">确认处理</button></div>`);$('adminAbort').onclick=()=>reportId?adminReportReview(reportId):adminEntity(scope,id);$('adminConfirm').onclick=()=>{try{adminDisposition(scope,id,action,$('adminReason').value,reportId);$('dialog').close();openAdmin(scope==='shop'?'shops':'products',reportId?'reports':'list');toast('已处理，商家通知与记录已更新');}catch(e){$('adminError').textContent=e.message;}};}
function adminReportReview(id){const r=demoReports.find(r=>r.id===id);if(!r)return;modal('举报核查',`<h3>${escapeHTML(r.target.name)}</h3><p>${escapeHTML(r.reason)}</p><p class="reportDescription">${escapeHTML(r.description)}</p><span class="tag">${r.status}</span>${r.status==='已处理'?`<p>${escapeHTML(r.result)}</p>`:`<div class="adminControls"><button id="reportWarn">警告商家</button>${r.target.kind==='product'?'<button id="reportEmergency">紧急下架该商品</button>':''}<button id="reportStop">暂停店铺</button><button id="reportClear">未发现违规</button></div>`}`);if(r.status==='待处理'){const scope=r.target.kind==='product'?'product':'shop',target=r.target.kind==='product'?r.target.id:r.target.shop;$('reportWarn').onclick=()=>adminActionForm(scope,target,'warn',id);if($('reportEmergency'))$('reportEmergency').onclick=()=>adminActionForm('product',r.target.id,'emergency',id);$('reportStop').onclick=()=>adminActionForm('shop',r.target.shop,'stop',id);$('reportClear').onclick=()=>adminActionForm(scope,target,'clear',id);}}
function adminRequestReview(scope,id){const s=scope==='shop'?shopSupervision[id]:productControl(id),q=s.request;modal('整改申请审核',`<span class="tag">${q.status}</span><p class="reportDescription">${escapeHTML(q.reason)}</p>${q.result?`<p>审核结果：${escapeHTML(q.result)}</p>`:''}${q.status==='待审核'?'<label class="reportField">审核说明<textarea id="reviewReason"></textarea></label><p id="reviewError" role="alert"></p><div class="orderActions"><button id="reviewReject">驳回</button><button id="reviewApprove" class="primary">通过</button></div>':''}`);if(q.status!=='待审核')return;const decide=action=>{try{const reason=$('reviewReason').value.trim()||(action==='approve'?'整改复核通过':'');adminDisposition(scope,id,action,reason);$('dialog').close();openAdmin(scope==='shop'?'shops':'products','requests');}catch(e){$('reviewError').textContent=e.message;}};$('reviewReject').onclick=()=>decide('reject');$('reviewApprove').onclick=()=>decide('approve');}
function reviewApplication(){const q=shopApplication;reviewTextRecord('开店申请',`${applicationSummary(q)}`,q.status==='PENDING',(yes,reason)=>{q.status=yes?'APPROVED':'REJECTED';q.reason=reason;if(yes)shops[0]=q.name;adminLog('shop',0,yes?'开店审核通过':'开店审核驳回',reason);});}
function reviewQualification(){const q=qualificationRecord;reviewTextRecord('专项资质',`<p>${escapeHTML(q.type)} · ${escapeHTML(q.number)}</p><p>有效期：${q.expiry}</p>`,q.status==='待审核',(yes,reason)=>{if(yes&&q.expiry<new Date().toLocaleDateString('sv-SE'))throw Error('资质已过期，不能通过');q.status=yes?'已通过':'已驳回';q.reason=reason;adminLog('shop',0,yes?'资质审核通过':'资质审核驳回',reason);});}
function reviewTextRecord(title,body,pending,commit){modal(title+' · 模拟审核',body+'<p class="muted">文字资料用于课程演示，不代表证件真实性核验。</p>'+(!pending?'<p>当前申请已处理</p>':'<label class="reportField">审核说明<textarea id="textReviewReason"></textarea></label><p id="textReviewError" role="alert"></p><div class="orderActions"><button id="textReject">驳回</button><button id="textApprove" class="primary">通过</button></div>'));if(!pending)return;let done=false;const decide=yes=>{if(done)return;try{const reason=$('textReviewReason').value.trim()||(yes?'模拟审核通过':'');if(!reason)throw Error('请填写驳回原因');commit(yes,reason);done=true;$('dialog').close();drawAdmin();}catch(e){$('textReviewError').textContent=e.message;}};$('textReject').onclick=()=>decide(false);$('textApprove').onclick=()=>decide(true);}
function seedAdmin(){if(!shopApplication)shopApplication={name:'青禾校园小店',subject:'校园示例主体',license:'DEMO-001',status:'PENDING',reference:'ADMIN-DEMO',submittedAt:new Date().toLocaleString('zh-CN')};if(!qualificationRecord)qualificationRecord={type:'专项许可证（演示）',number:'DEMO-Q001',expiry:'2027-12-31',status:'待审核'};if(!demoReports.some(r=>r.id==='ADMIN-REPORT')){const p=[...adminCatalog.values()].find(p=>p.shop===0);demoReports.unshift({id:'ADMIN-REPORT',target:{kind:'product',id:p.id,shop:0,name:p.name},reason:'商品信息虚假或误导',description:'演示举报：请核查该商品的描述内容。',status:'待处理',images:[],createdAt:new Date().toLocaleString('zh-CN')});}drawAdmin();toast('演示申请与商品举报已载入');}
const adminEntry=document.createElement('button');adminEntry.id='adminEntry';adminEntry.textContent='管理员预览';adminEntry.onclick=()=>openAdmin();document.querySelector('header .nav').append(adminEntry);
window.addEventListener('hashchange',()=>{if(location.hash.startsWith('#admin-'))openAdmin(location.hash.slice(7));else adminPage.hidden=true;});
if(location.hash.startsWith('#admin-'))openAdmin(location.hash.slice(7));
